# Great! ping_group_range allows all groups (0 to 2147483647), so unprivileged ICMP is available
# This means using net.Dial("ip4:icmp", ...) should work as unprivileged

# Let me write a simple test
cat > /tmp/test_icmp.go << 'EOF'
package main

import (
	"fmt"
	"net"
	"time"
	"encoding/binary"
	"os"
)

func main() {
	// Test unprivileged ICMP
	conn, err := net.Dial("ip4:icmp", "127.0.0.1")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		// Try UDP approach
		conn2, err2 := net.ListenPacket("udp4", "0.0.0.0:0")
		if err2 != nil {
			fmt.Fprintf(os.Stderr, "UDP Error: %v\n", err2)
			return
		}
		defer conn2.Close()
		fmt.Println("UDP approach works:", conn2.LocalAddr())
		return
	}
	defer conn.Close()

	// Build ICMP echo request
	// Type=8 (Echo Request), Code=0, Checksum, ID, Seq, Data
	id := 1234
	seq := 1
	data := []byte("Hello World 12345678") // 20 bytes

	packet := make([]byte, 8+len(data))
	packet[0] = 8  // Type: Echo Request
	packet[1] = 0  // Code: 0
	packet[2] = 0  // Checksum high
	packet[3] = 0  // Checksum low
	binary.BigEndian.PutUint16(packet[4:], uint16(id))
	binary.BigEndian.PutUint16(packet[6:], uint16(seq))
	copy(packet[8:], data)

	// Compute checksum
	checksum := computeChecksum(packet)
	packet[2] = byte(checksum >> 8)
	packet[3] = byte(checksum)

	start := time.Now()
	_, err = conn.Write(packet)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Write error: %v\n", err)
		return
	}

	reply := make([]byte, 1500)
	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	n, err := conn.Read(reply)
	elapsed := time.Since(start)

	if err != nil {
		fmt.Fprintf(os.Stderr, "Read error: %v\n", err)
		return
	}

	fmt.Printf("Got %d bytes, time=%v\n", n, elapsed)
}

func computeChecksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(binary.BigEndian.Uint16(data[i:]))
	}
	if len(data)%2 != 0 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}
EOF

cd /tmp && go run test_icmp.go

