# So raw IP sockets require privilege. We need to use the UDP approach.
# The go-ping library uses "github.com/sparrc/go-ping" which does this.
# Let me understand the UDP approach for ICMP better.

# On Linux with ping_group_range set, you can use SOCK_DGRAM with IPPROTO_ICMP
# This is what go-ping does - it uses syscall to create the socket

# Let me implement this from scratch using syscall
cat > /tmp/test_icmp2.go << 'EOF'
package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"os"
	"syscall"
	"time"
)

func computeChecksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(binary.BigEndian.Uint16(data[i:]))
	}
	if len(data)%2 != 0 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

func main() {
	// Create ICMP socket using SOCK_DGRAM (unprivileged)
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Socket error: %v\n", err)
		return
	}
	defer syscall.Close(fd)

	fmt.Printf("Socket fd: %d\n", fd)

	// Bind
	err = syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0})
	if err != nil {
		fmt.Fprintf(os.Stderr, "Bind error: %v\n", err)
		return
	}

	// Get local addr
	laddr, err := syscall.Getsockname(fd)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Getsockname error: %v\n", err)
		return
	}
	if la, ok := laddr.(*syscall.SockaddrInet4); ok {
		fmt.Printf("Local addr: %v:%d\n", net.IP(la.Addr[:]), la.Port)
	}

	// Build ICMP echo request
	id := uint16(12345)
	seq := uint16(1)
	payload := make([]byte, 24) // some payload

	packet := make([]byte, 8+len(payload))
	packet[0] = 8  // Echo Request
	packet[1] = 0  // Code
	packet[2] = 0  // Checksum
	packet[3] = 0
	binary.BigEndian.PutUint16(packet[4:], id)
	binary.BigEndian.PutUint16(packet[6:], seq)
	copy(packet[8:], payload)

	csum := computeChecksum(packet)
	binary.BigEndian.PutUint16(packet[2:], csum)

	dst := syscall.SockaddrInet4{Port: 0}
	copy(dst.Addr[:], net.ParseIP("127.0.0.1").To4())

	start := time.Now()
	err = syscall.Sendto(fd, packet, 0, &dst)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Sendto error: %v\n", err)
		return
	}

	reply := make([]byte, 1500)
	// Set timeout
	tv := syscall.Timeval{Sec: 5, Usec: 0}
	syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

	n, from, err := syscall.Recvfrom(fd, reply, 0)
	elapsed := time.Since(start)

	if err != nil {
		fmt.Fprintf(os.Stderr, "Recvfrom error: %v\n", err)
		return
	}

	_ = from
	fmt.Printf("Received %d bytes, time=%v\n", n, elapsed)
	fmt.Printf("Reply type: %d, code: %d\n", reply[0], reply[1])
}
EOF

cd /tmp && go run test_icmp2.go

