	// ICMP message types
	ICMPTypeEchoRequest = 8
	ICMPTypeEchoReply   = 0

	// Payload size: total ICMP message = 8 (header) + 24 (data) = 32 bytes
	ICMP_DATA_SIZE = 24

	// Ping interval
	PING_INTERVAL = 1 * time.Second

	// Ping timeout
	PING_TIMEOUT = 10 * time.Second
)

// Penguin art - 20 rows, each row is exactly 50 chars (padded to 58 with spaces)
var pinguArt = []string{
	" ...        .     ...   ..    ..     .........      ",
	" ...     ....          ..  ..      ... .....  .. .. ",
	" ...    .......      ...         ... . ..... ####### ",
	".....  ........ .###############.....  ... ##########.  .",
	" .... ........#####################.  ... ###########   ",
	"      ....... ######################.... ############   ",
	".    .  .... ########################... ###########    ",
	"   ..   ....#########################.. .###########    ",
	"    .       #########################.   .##########    ",
	"   ....     .########################.      ########    ",
	"  .....      .  ####################.        #######.   ",
	"......     .. . ################## . .      .#######    ",
	"......       #####################  .      .#######     ",
	"......   .###########################  ..  #######     ",
	"...    . ########################################.       ",
	"       ####################################### .        ",
	"      ##################################    .           ",
	"     ###################################  ........      ",
	"  .#####################################    .........   ",
	" .#######################################       .... . . ",
}

func computeChecksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(binary.BigEndian.Uint16(data[i:]))
	}
	if len(data)%2 != 0 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

type PingResult struct {
	Seq     int
	IP      net.IP
	TTL     int
	RTT     time.Duration
	Timeout bool
}

type Stats struct {
	Sent     int
	Received int
	RTTs     []time.Duration
}

func (s *Stats) Min() time.Duration {
	if len(s.RTTs) == 0 {
		return 0
	}
	min := s.RTTs[0]
	for _, rtt := range s.RTTs[1:] {
		if rtt < min {
			min = rtt
		}
	}
	return min
}

func (s *Stats) Max() time.Duration {
	if len(s.RTTs) == 0 {
		return 0
	}
	max := s.RTTs[0]
	for _, rtt := range s.RTTs[1:] {
		if rtt > max {
			max = rtt
		}
	}
	return max
}

func (s *Stats) Avg() time.Duration {
	if len(s.RTTs) == 0 {
		return 0
	}
	var total time.Duration
	for _, rtt := range s.RTTs {
		total += rtt
	}
	return total / time.Duration(len(s.RTTs))
}

func (s *Stats) StdDev() time.Duration {
	if len(s.RTTs) <= 1 {
		return 0
	}
	avg := float64(s.Avg())
	var variance float64
	for _, rtt := range s.RTTs {
		diff := float64(rtt) - avg
		variance += diff * diff
	}
	variance /= float64(len(s.RTTs))
	return time.Duration(math.Sqrt(variance))
}

func printUsage() {
	fmt.Println(`
Usage:
  pingu [OPTIONS] HOST

` + "`ping` command but with pingu" + `

Application Options:
  -c, --count=     Stop after <count> replies (default: 20)
  -P, --privilege  Enable privileged mode
  -V, --version    Show version

Help Options:
  -h, --help       Show this help message
`)
}

func main() {
	// Parse arguments manually to match go-flags format
	var count int = 20
	var privilege bool = false
	var host string

	args := os.Args[1:]
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "-h", "--help":
			printUsage()
			os.Exit(0)
		case "-V", "--version":
			fmt.Printf("pingu: %s\n", VERSION)
			os.Exit(0)
		case "-P", "--privilege":
			privilege = true
			i++
		case "-c", "--count":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "[ ERROR ] parse error: expected argument for flag `-c, --count'\n")
				os.Exit(1)
			}
			n := 0
			_, err := fmt.Sscanf(args[i], "%d", &n)
			if err != nil {
				fmt.Fprintf(os.Stderr, "invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing %q: invalid syntax\n", args[i])
				fmt.Fprintf(os.Stderr, "[ ERROR ] parse error: invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing %q: invalid syntax\n", args[i])
				os.Exit(1)
			}
			count = n
			i++
		default:
			if len(arg) > 0 && arg[0] == '-' {
				fmt.Fprintf(os.Stderr, "[ ERROR ] parse error: unknown flag `%s'\n", arg)
				os.Exit(1)
			}
			host = arg
			i++
		}
	}

	if host == "" {
		fmt.Fprintf(os.Stderr, "[ ERROR ] must requires an argument\n")
		os.Exit(1)
	}

	// Resolve host
	ips, err := net.LookupHost(host)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[ ERROR ] %v\n", err)
		os.Exit(1)
	}

	destIP := net.ParseIP(ips[0])
	if destIP == nil {
		fmt.Fprintf(os.Stderr, "[ ERROR ] invalid IP: %s\n", ips[0])
		os.Exit(1)
	}

	fmt.Printf("PING %s (%s) type `Ctrl-C` to abort\n", host, destIP.String())

	stats := &Stats{}

	// Set up signal handler
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	pingCh := make(chan PingResult, 1)

	// Create ICMP socket
	if privilege {
		// Privileged mode using raw socket
		runPingPrivileged(host, destIP, count, stats, sigCh, pingCh)
	} else {
		// Unprivileged mode using SOCK_DGRAM
		runPingUnprivileged(host, destIP, count, stats, sigCh, pingCh)
	}

	// Print stats
	printStats(host, destIP, stats)
}

func runPingUnprivileged(host string, destIP net.IP, count int, stats *Stats, sigCh chan os.Signal, pingCh chan PingResult) {
	// Create ICMP socket using SOCK_DGRAM (unprivileged)
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[ ERROR ] an error occurred when running ping: %v\n", err)
		printStats(host, destIP, stats)
		os.Exit(2)
	}
	defer syscall.Close(fd)

	// Bind
	err = syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0})
	if err != nil {
		fmt.Fprintf(os.Stderr, "[ ERROR ] an error occurred when running ping: %v\n", err)
		printStats(host, destIP, stats)
		os.Exit(2)
	}

	// Enable receiving TTL
	err = syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
	if err != nil {
