cat > /tmp/test_dgram_icmp.go << 'EOF'
package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"os"
	"syscall"
	"time"
	"unsafe"
)

func computeChecksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(binary.BigEndian.Uint16(data[i:]))
	}
	if len(data)%2 != 0 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

// Make a sendmsg-based write that produces the same error format as go-ping
func main() {
	// Use SOCK_DGRAM with IPPROTO_ICMP - this is what go-ping uses for unprivileged
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Socket error: %v\n", err)
		return
	}
	defer syscall.Close(fd)

	// Bind to get a port
	bindAddr := syscall.SockaddrInet4{Port: 0}
	if err := syscall.Bind(fd, &bindAddr); err != nil {
		fmt.Fprintf(os.Stderr, "Bind error: %v\n", err)
		return
	}

	// Get local address
	laddr, _ := syscall.Getsockname(fd)
	var localPort int
	if la, ok := laddr.(*syscall.SockaddrInet4); ok {
		localPort = la.Port
		fmt.Printf("Local port: %d\n", localPort)
	}

	// Enable IP_RECVTTL
	if err := syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1); err != nil {
		fmt.Fprintf(os.Stderr, "IP_RECVTTL error: %v\n", err)
	}

	// Build ICMP echo request (32 bytes = 8 header + 24 data)
	packet := make([]byte, 32)
	packet[0] = 8  // Echo Request
	packet[1] = 0  // Code
	binary.BigEndian.PutUint16(packet[4:], uint16(localPort)) // ID
	binary.BigEndian.PutUint16(packet[6:], 1) // Seq
	csum := computeChecksum(packet)
	binary.BigEndian.PutUint16(packet[2:], csum)

	// Send to 127.0.0.1
	dst := syscall.SockaddrInet4{Port: 0}
	copy(dst.Addr[:], net.ParseIP("127.0.0.1").To4())

	start := time.Now()
	if err := syscall.Sendto(fd, packet, 0, &dst); err != nil {
		fmt.Fprintf(os.Stderr, "Sendto error: %v\n", err)
		return
	}

	// Receive
	reply := make([]byte, 1500)
	oob := make([]byte, 256)

	tv := syscall.NsecToTimeval(int64(10 * time.Second))
	syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

	n, oobn, _, from, err := syscall.Recvmsg(fd, reply, oob, 0)
	elapsed := time.Since(start)

	if err != nil {
		fmt.Fprintf(os.Stderr, "Recvmsg error: %v\n", err)
		return
	}

	ttl := 64
	if oobn > 0 {
		msgs, err := syscall.ParseSocketControlMessage(oob[:oobn])
		if err == nil {
			for _, msg := range msgs {
				if msg.Header.Level == syscall.IPPROTO_IP && int(msg.Header.Type) == syscall.IP_TTL {
					if len(msg.Data) >= 1 {
						ttl = int(msg.Data[0])
					}
					if len(msg.Data) >= 4 {
						ttl = int(binary.LittleEndian.Uint32(msg.Data))
					}
				}
			}
		}
	}

	_ = from
	fmt.Printf("n=%d, oobn=%d, ttl=%d, elapsed=%v\n", n, oobn, ttl, elapsed)

	// Also show the from addr
	if fa, ok := from.(*syscall.SockaddrInet4); ok {
		fmt.Printf("From: %v:%d\n", net.IP(fa.Addr[:]), fa.Port)
	}

	// Test with 8.8.8.8 (should fail with sendmsg error)
	dst2 := syscall.SockaddrInet4{Port: 0}
	copy(dst2.Addr[:], net.ParseIP("8.8.8.8").To4())

	// Try using iovec with sendmsg
	iov := syscall.Iovec{Base: &packet[0], Len: uint64(len(packet))}
	msghdr := syscall.Msghdr{
		Iov: &iov,
		Iovlen: 1,
	}
	// Set destination
	rawDst := syscall.RawSockaddrInet4{
		Family: syscall.AF_INET,
		Port:   0,
		Addr:   [4]byte{8, 8, 8, 8},
	}
	msghdr.Name = (*byte)(unsafe.Pointer(&rawDst))
	msghdr.Namelen = uint32(unsafe.Sizeof(rawDst))

	_, _, errno := syscall.Syscall(syscall.SYS_SENDMSG, uintptr(fd), uintptr(unsafe.Pointer(&msghdr)), 0)
	if errno != 0 {
		fmt.Fprintf(os.Stderr, "sendmsg to 8.8.8.8 error: %v\n", errno)
	} else {
		fmt.Println("sendmsg to 8.8.8.8 succeeded!")
	}
}
EOF

