	// ICMP message types
	ICMPTypeEchoRequest = 8
	ICMPTypeEchoReply   = 0

	// Payload size: total ICMP = 8 (header) + 24 (data) = 32 bytes
	ICMP_DATA_SIZE = 24

	// Ping interval
	PING_INTERVAL = 1 * time.Second

	// Ping timeout
	PING_TIMEOUT = 10 * time.Second
)

// Penguin art rows - each exactly 58 chars
var pinguArt = [20]string{
	" ...        .     ...   ..    ..     .........            ",
	" ...     ....          ..  ..      ... .....  .. ..       ",
	" ...    .......      ...         ... . ..... #######      ",
	".....  ........ .###############.....  ... ##########.  . ",
	" .... ........#####################.  ... ###########     ",
	"      ....... ######################.... ############     ",
	".    .  .... ########################... ###########      ",
	"   ..   ....#########################.. .###########      ",
	"    .       #########################.   .##########      ",
	"   ....     .########################.      ########      ",
	"  .....      .  ####################.        #######.     ",
	"......     .. . ################## . .      .#######      ",
	"......       #####################  .      .#######       ",
	"......   .###########################  ..  #######        ",
	"...    . ########################################.        ",
	"       ####################################### .          ",
	"      ##################################    .             ",
	"     ###################################  ........        ",
	"  .#####################################    .........     ",
	" .#######################################       .... . .  ",
}

func computeChecksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(binary.BigEndian.Uint16(data[i:]))
	}
	if len(data)%2 != 0 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

type Stats struct {
	Sent     int
	Received int
	RTTs     []time.Duration
}

func (s *Stats) Min() time.Duration {
	if len(s.RTTs) == 0 {
		return 0
	}
	min := s.RTTs[0]
	for _, rtt := range s.RTTs[1:] {
		if rtt < min {
			min = rtt
		}
	}
	return min
}

func (s *Stats) Max() time.Duration {
	if len(s.RTTs) == 0 {
		return 0
	}
	max := s.RTTs[0]
	for _, rtt := range s.RTTs[1:] {
		if rtt > max {
			max = rtt
		}
	}
	return max
}

func (s *Stats) Avg() time.Duration {
	if len(s.RTTs) == 0 {
		return 0
	}
	var total time.Duration
	for _, rtt := range s.RTTs {
		total += rtt
	}
	return total / time.Duration(len(s.RTTs))
}

func (s *Stats) StdDev() time.Duration {
	if len(s.RTTs) <= 1 {
		return 0
	}
	avg := float64(s.Avg())
	var variance float64
	for _, rtt := range s.RTTs {
		diff := float64(rtt) - avg
		variance += diff * diff
	}
	variance /= float64(len(s.RTTs))
	return time.Duration(math.Sqrt(variance))
}

func printUsage() {
	fmt.Print(`
Usage:
  pingu [OPTIONS] HOST

` + "`ping` command but with pingu" + `

Application Options:
  -c, --count=     Stop after <count> replies (default: 20)
  -P, --privilege  Enable privileged mode
  -V, --version    Show version

Help Options:
  -h, --help       Show this help message

`)
}

// flagsError writes error to stdout then prefixes to stderr (mimicking go-flags)
func flagsError(msg string) {
	fmt.Println(msg)
	fmt.Fprintf(os.Stderr, "[ ERROR ] parse error: %s\n", msg)
	os.Exit(1)
}

func parseArgs() (host string, count int, privilege bool) {
	count = 20
	args := os.Args[1:]
	i := 0
	for i < len(args) {
		arg := args[i]

		if arg == "--" {
			i++
			// Remaining args are positional
			for ; i < len(args); i++ {
				if host != "" {
					fmt.Fprintf(os.Stderr, "[ ERROR ] too many arguments\n")
					os.Exit(1)
				}
				host = args[i]
			}
			break
		}

		if strings.HasPrefix(arg, "--") {
			// Long flag
			name := arg[2:]
			var value string
			hasValue := false
			if idx := strings.Index(name, "="); idx != -1 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}

			switch name {
			case "help":
				printUsage()
				os.Exit(0)
			case "version":
				fmt.Printf("pingu: %s\n", VERSION)
				os.Exit(0)
			case "privilege":
				privilege = true
				i++
			case "count":
				if !hasValue {
					i++
					if i >= len(args) {
						flagsError("expected argument for flag `-c, --count'")
					}
					value = args[i]
				}
				n, err := strconv.ParseInt(value, 10, 64)
				if err != nil {
					flagsError(fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): %v", err))
				}
				count = int(n)
				i++
			default:
				flagsError(fmt.Sprintf("unknown flag `%s'", name))
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flag(s)
			// go-flags processes one short flag at a time
			flag := arg[1:]
			// For go-flags, -abc is treated as -a -b -c for boolean flags
			// but for value flags, -c VALUE or -cVALUE

			// Process first char
			ch := flag[0]
			rest := flag[1:]

			switch ch {
			case 'h':
				printUsage()
				os.Exit(0)
			case 'V':
				fmt.Printf("pingu: %s\n", VERSION)
				os.Exit(0)
			case 'P':
				privilege = true
				if len(rest) > 0 {
					// Put back the rest as a new arg
					args[i] = "-" + rest
				} else {
					i++
				}
			case 'c':
				var value string
				if len(rest) > 0 {
					value = rest
					i++
				} else {
					i++
					if i >= len(args) {
						flagsError("expected argument for flag `-c, --count'")
					}
					value = args[i]
					i++
				}
				n, err := strconv.ParseInt(value, 10, 64)
				if err != nil {
					flagsError(fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): %v", err))
				}
				count = int(n)
			default:
				flagsError(fmt.Sprintf("unknown flag `%c'", ch))
			}
		} else {
			// Positional argument
			if host != "" {
				fmt.Fprintf(os.Stderr, "[ ERROR ] too many arguments\n")
				os.Exit(1)
			}
			host = arg
			i++
		}
	}
	return
}

func printStats(host string, stats *Stats) {
	fmt.Println()
	fmt.Printf("───────── %s ping statistics ─────────\n", host)

	loss := 0
	if stats.Sent > 0 {
		loss = (stats.Sent - stats.Received) * 100 / stats.Sent
	}
	fmt.Printf("PACKET STATISTICS: %d transmitted => %d received (%d%% loss)\n",
		stats.Sent, stats.Received, loss)

	min := stats.Min()
	avg := stats.Avg()
	max := stats.Max()
	stddev := stats.StdDev()

	fmt.Printf("ROUND TRIP: min=%s avg=%s max=%s stddev=%s\n",
		min, avg, max, stddev)
}

func runPingUnprivileged(host string, destIP net.IP, count int, stats *Stats) error {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		return fmt.Errorf("socket error: %v", err)
	}
	defer syscall.Close(fd)

	if err := syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0}); err != nil {
		return fmt.Errorf("bind error: %v", err)
	}

	if err := syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1); err != nil {
		// Non-fatal
	}

	// Get local address for error reporting and ICMP ID
	laddr, _ := syscall.Getsockname(fd)
	var localPort int
	if la, ok := laddr.(*syscall.SockaddrInet4); ok {
		localPort = la.Port
	}

	dst := syscall.SockaddrInet4{Port: 0}
	ip4 := destIP.To4()
	copy(dst.Addr[:], ip4)

	// Set up signal handler
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	ticker := time.NewTicker(PING_INTERVAL)
	defer ticker.Stop()

	seq := 0
	for {
		// Check if we should stop
		if count > 0 && seq >= count {
			break
		}

		// Build ICMP echo request
		packet := make([]byte, 8+ICMP_DATA_SIZE)
		packet[0] = ICMPTypeEchoRequest
		packet[1] = 0
		binary.BigEndian.PutUint16(packet[4:], uint16(localPort))
		binary.BigEndian.PutUint16(packet[6:], uint16(seq))
		csum := computeChecksum(packet)
		binary.BigEndian.PutUint16(packet[2:], csum)

		start := time.Now()
		sendErr := syscall.Sendto(fd, packet, 0, &dst)
		if sendErr != nil {
			// Format error like Go net package
			return fmt.Errorf("write udp 0.0.0.0:%d->%s:0: sendmsg: %v",
				localPort, destIP.String(), sendErr)
		}
		stats.Sent++

		// Receive reply
		reply := make([]byte, 1500)
		oob := make([]byte, 256)

		tv := syscall.NsecToTimeval(int64(PING_TIMEOUT))
		syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

		n, oobn, _, _, recvErr := syscall.Recvmsg(fd, reply, oob, 0)
		rtt := time.Since(start)

		_ = n

		if recvErr != nil {
			// Timeout or error - print timeout
			artRow := pinguArt[seq%len(pinguArt)]
			fmt.Printf("%sseq=%d timeout\n", artRow, seq)
		} else {
			// Parse TTL from OOB
			ttl := 64
			if oobn > 0 {
				msgs, err := syscall.ParseSocketControlMessage(oob[:oobn])
				if err == nil {
					for _, msg := range msgs {
						if msg.Header.Level == syscall.IPPROTO_IP && int(msg.Header.Type) == syscall.IP_TTL {
							if len(msg.Data) >= 4 {
								ttl = int(binary.LittleEndian.Uint32(msg.Data))
							} else if len(msg.Data) >= 1 {
								ttl = int(msg.Data[0])
							}
						}
					}
				}
			}

			stats.Received++
			stats.RTTs = append(stats.RTTs, rtt)

			artRow := pinguArt[seq%len(pinguArt)]
			fmt.Printf("%sseq=%d 32bytes from %s: ttl=%d time=%s\n",
				artRow, seq, destIP.String(), ttl, rtt)
		}

		seq++

		if count > 0 && seq >= count {
			break
		}

		// Wait for next ping or signal
		select {
		case <-ticker.C:
			// continue
		case <-sigCh:
			return nil
		}
	}

