func runPingUnprivileged(host string, destIP net.IP, count int, stats *Stats, sigCh chan os.Signal) error {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		return fmt.Errorf("socket: %v", err)
	}
	defer syscall.Close(fd)

	if err := syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0}); err != nil {
		return fmt.Errorf("bind: %v", err)
	}

	// Enable receiving TTL via ancillary data
	if err := syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1); err != nil {
		// Non-fatal warning
	}

	// Get local address for ICMP ID and error reporting
	laddr, _ := syscall.Getsockname(fd)
	var localPort int
	if la, ok := laddr.(*syscall.SockaddrInet4); ok {
		localPort = la.Port
	}

	dst := syscall.SockaddrInet4{Port: 0}
	ip4 := destIP.To4()
	if ip4 == nil {
		return fmt.Errorf("not an IPv4 address: %s", destIP)
	}
	copy(dst.Addr[:], ip4)

	ticker := time.NewTicker(PING_INTERVAL)
	defer ticker.Stop()

	seq := 0
	for {
		if count > 0 && seq >= count {
			break
		}

		// Build ICMP echo request
		packet := make([]byte, 8+ICMP_DATA_SIZE)
		packet[0] = ICMPTypeEchoRequest
		packet[1] = 0
		binary.BigEndian.PutUint16(packet[4:], uint16(localPort))
		binary.BigEndian.PutUint16(packet[6:], uint16(seq))
		csum := computeChecksum(packet)
		binary.BigEndian.PutUint16(packet[2:], csum)

		start := time.Now()
		sendErr := syscall.Sendto(fd, packet, 0, &dst)
		if sendErr != nil {
			return fmt.Errorf("write udp 0.0.0.0:%d->%s:0: sendmsg: %v",
				localPort, destIP.String(), sendErr)
		}
		stats.Sent++

		// Receive reply with timeout
		reply := make([]byte, 1500)
		oob := make([]byte, 256)

		tv := syscall.NsecToTimeval(int64(PING_TIMEOUT))
		syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

		n, oobn, _, _, recvErr := syscall.Recvmsg(fd, reply, oob, 0)
		rtt := time.Since(start)
		_ = n

		artRow := pinguArt[seq%len(pinguArt)]

		if recvErr != nil {
			fmt.Printf("%sseq=%d timeout\n", artRow, seq)
		} else {
			// Parse TTL from OOB ancillary data
			ttl := 64
			if oobn > 0 {
				msgs, err := syscall.ParseSocketControlMessage(oob[:oobn])
				if err == nil {
					for _, msg := range msgs {
						if msg.Header.Level == syscall.IPPROTO_IP && int(msg.Header.Type) == syscall.IP_TTL {
							if len(msg.Data) >= 4 {
								ttl = int(binary.LittleEndian.Uint32(msg.Data))
							} else if len(msg.Data) >= 1 {
								ttl = int(msg.Data[0])
							}
						}
					}
				}
			}

			stats.Received++
			stats.RTTs = append(stats.RTTs, rtt)

			fmt.Printf("%sseq=%d 32bytes from %s: ttl=%d time=%s\n",
				artRow, seq, destIP.String(), ttl, rtt)
		}

		seq++

		if count > 0 && seq >= count {
			break
		}

		// Wait for next tick or signal
		select {
		case <-ticker.C:
		case <-sigCh:
			return nil
		}
	}

	return nil
}

func runPingPrivileged(host string, destIP net.IP, count int, stats *Stats, sigCh chan os.Signal) error {
	conn, err := net.ListenPacket("ip4:icmp", "")
	if err != nil {
		return err
	}
	defer conn.Close()

	ticker := time.NewTicker(PING_INTERVAL)
	defer ticker.Stop()

	id := os.Getpid() & 0xffff
	seq := 0

	for {
		if count > 0 && seq >= count {
			break
		}

		// Build ICMP echo request
		packet := make([]byte, 8+ICMP_DATA_SIZE)
		packet[0] = ICMPTypeEchoRequest
		packet[1] = 0
		binary.BigEndian.PutUint16(packet[4:], uint16(id))
		binary.BigEndian.PutUint16(packet[6:], uint16(seq))
		csum := computeChecksum(packet)
		binary.BigEndian.PutUint16(packet[2:], csum)

		dst := &net.IPAddr{IP: destIP}
		start := time.Now()
		_, sendErr := conn.WriteTo(packet, dst)
		if sendErr != nil {
			return sendErr
		}
		stats.Sent++

		// Receive reply
		reply := make([]byte, 1500)
		conn.SetReadDeadline(time.Now().Add(PING_TIMEOUT))
		n, _, recvErr := conn.ReadFrom(reply)
		rtt := time.Since(start)

		artRow := pinguArt[seq%len(pinguArt)]

		if recvErr != nil {
			fmt.Printf("%sseq=%d timeout\n", artRow, seq)
		} else {
			// For privileged raw socket: TTL is in IP header
			// When using net.ListenPacket("ip4:icmp"), Linux includes IP header
			ttl := 64
			if n >= 9 {
				// IP header: version/ihl, tos, len(2), id(2), flags/offset(2), TTL, proto, checksum(2), src(4), dst(4)
				// But net package may strip IP header...
				// Actually for raw ICMP sockets, the reply includes IP header
				// IP header TTL is at byte 8 (0-indexed)
				ttl = int(reply[8])
			}

			stats.Received++
			stats.RTTs = append(stats.RTTs, rtt)

			fmt.Printf("%sseq=%d 32bytes from %s: ttl=%d time=%s\n",
				artRow, seq, destIP.String(), ttl, rtt)
		}

		seq++

		if count > 0 && seq >= count {
			break
		}

		select {
		case <-ticker.C:
		case <-sigCh:
			return nil
		}
	}

	return nil
}

